"""Author: Andrew Fisher. Incomplete customer evidence uses existing review/subtotal handling."""

def patch(text,rep,path):
    changes=[
      (' const peopleExact = lines.reduce((s, l) => s + l.amount_exact, 0);',
       " const customerReview12451=lines.map(line=>line.customer_hours_review12451).filter(Boolean);\n const peopleExact = lines.reduce((s, l) => s + l.amount_exact, 0);",
       'retain an explicit scope review state'),
      ("document: SCOPE.document, supplied_by: SCOPE.supplied_by, supplied_on: SCOPE.supplied_on, provisional: /to be updated/i.test(SCOPE.access_plan.as_written || '')};",
       "document: SCOPE.document, supplied_by: SCOPE.supplied_by, supplied_on: SCOPE.supplied_on, provisional: /to be updated/i.test(SCOPE.access_plan.as_written || ''),...(customerReview12451.length?{customer_review12451:customerReview12451}:{})};",
       'customer review does not change the source access-plan status'),
      ('<tr class="total"><td><b>Event labour, charged</b></td>',
       '<tr class="total"><td><b>${F.customer_review12451 ? \'Event labour — known subtotal\' : \'Event labour, charged\'}</b></td>',
       'label partial event subtotal'),
      ('race: SF ? {amount: SF.total, scope: true, people_amount: SF.people,',
       'race: SF ? {amount: SF.total, scope: true,...(SF.customer_review12451?{customer_review12451:SF.customer_review12451}:{}), people_amount: SF.people,',
       'carry missing customer hours into shared charge metadata'),
      ('const miss = (l, sh) => { missing.push(l); short.push(sh); };',
       "const miss = (l, sh) => { missing.push(l); short.push(sh); };\n if(SF?.customer_review12451?.length)miss(SF.customer_review12451.join(' '),'known charge subtotal excludes unconfirmed customer fencing hours');",
       'use native missing-charge explanations'),
      ('if(line)o.charge={hours:line.hours,rate:line.rate,amount:line.amount};',
       'if(line)o.charge={hours:line.hours,rate:line.rate,amount:line.amount,...(line.customer_hours_review12451?{review12451:line.customer_hours_review12451}:{})};',
       'supplier model customer reference retains unavailable status'),
      ("(how==='charge'&&m.charge?' · customer event scope: '+fmtNum(m.charge.hours)+' h at '+money(m.charge.rate)+' = '+money(m.charge.amount):'')",
       "(how==='charge'&&m.charge?(m.charge.review12451?' · customer fencing charge needs review; excluded from the known subtotal':' · customer event scope: '+fmtNum(m.charge.hours)+' h at '+money(m.charge.rate)+' = '+money(m.charge.amount)):'')",
       'documented supplier wording never shows unavailable customer charge as zero'),
      ("if(how==='charge'&&m.charge)s+=' · the V8s pay for this crew in the event labour scope: Fence team '+fmtNum(m.charge.hours)+' h at '+money(m.charge.rate)+' = '+money(m.charge.amount);",
       "if(how==='charge'&&m.charge)s+=m.charge.review12451?' · customer fencing charge needs review; excluded from the known subtotal':' · the V8s pay for this crew in the event labour scope: Fence team '+fmtNum(m.charge.hours)+' h at '+money(m.charge.rate)+' = '+money(m.charge.amount);",
       'forecast supplier wording retains customer review'),
      ("let scope = 0, scopeH = 0; try { const f = scopeFigures().lines.find(l => l.key === 'fence'); if (f) { scope = f.amount; scopeH = f.hours; } } catch (e) {}",
       "let scope = 0, scopeH = 0, scopeReview12451=null; try { const f = scopeFigures().lines.find(l => l.key === 'fence'); if (f) { scope = f.amount; scopeH = f.hours; scopeReview12451=f.customer_hours_review12451||null; } } catch (e) {}",
       'all-in fencing reads the shared customer review'),
      ('return {fd, types, inv, not, scope, scopeH, crew, cl, extrasCh, extrasPd, charge, cost};',
       'return {fd, types, inv, not, scope, scopeH, crew, cl, extrasCh, extrasPd, charge, cost,...(scopeReview12451?{scopeReview12451}:{})};',
       'all-in fencing keeps customer unknown separate from supplier cost'),
      ('<h3 style="margin:0 0 6px">Fencing, everything included</h3>',
       '<h3 style="margin:0 0 6px">${M.scopeReview12451?\'Fencing — known subtotal\':\'Fencing, everything included\'}</h3>',
       'partial fencing title does not claim completeness'),
      ('Charge to the V8s <b>${m(M.charge)}</b> · we pay',
       "${M.scopeReview12451?'Known charge subtotal':'Charge to the V8s'} <b>${m(M.charge)}</b> · we pay",
       'all-in fencing labels known subtotal'),
      ('· margin <b>${m(c2(M.charge - M.cost))}</b>. Every line is already in the job\'s total charge; this card only brings them together.',
       "· ${M.scopeReview12451?'difference on known subtotal':'margin'} <b>${m(c2(M.charge - M.cost))}</b>. ${M.scopeReview12451?'The unconfirmed customer fencing charge is excluded; review its source.':\"Every line is already in the job's total charge; this card only brings them together.\"}",
       'partial fencing result is not a complete margin'),
      ("${row('<b>Everything included</b>', '', `<b>${m(M.charge)}</b>`, `<b>${m(M.cost)}</b>`, 'tot')}",
       "${row(M.scopeReview12451?'<b>Known subtotal</b>':'<b>Everything included</b>', '', `<b>${m(M.charge)}</b>`, `<b>${m(M.cost)}</b>`, 'tot')}",
       'partial fencing footer labels known subtotal'),
      ("${row('Fence event labour, race days (event scope)', q(M.scopeH) + ' h', m(M.scope), '—')}",
       "${row('Fence event labour, race days (event scope)', M.scopeReview12451?'—':q(M.scopeH) + ' h', M.scopeReview12451?'Needs review':m(M.scope), '—')}",
       'all-in fencing never renders unavailable customer hours as zero'),
      (' /* revenue and direct costs, the whole job */',
       " if(race.customer_review12451?.length)tie('P&L','Documented customer fencing hours',[part('Customer hours need review',null)]);\n /* revenue and direct costs, the whole job */",
       'incomplete customer evidence cannot pass reconciliation'),
      (' const sourceAvailable=Array.isArray(m.onsiteComplete?.holds)',
       " const customerReview12451=array(m.eventScope?.customer_review12451);\n if(customerReview12451.length){include({ref:'Job',item:'Fencing event crew',charge:'Customer hours',reason:customerReview12451.join(' ')});add('Documented customer fencing hours',null,[null]);}\n const sourceAvailable=Array.isArray(m.onsiteComplete?.holds)",
       'existing assurance unavailable and review paths'),
      ('return {actual,job,fence,priced,remainingOther,checks,state,sourceAvailable,issues:[...issues.values()],roleRounding:',
       'return {actual,job,fence,priced,remainingOther,checks,state,sourceAvailable,...(customerReview12451.length?{customerReview12451}:{}),issues:[...issues.values()],roleRounding:',
       'assurance retains partial charge status'),
      ("const bridge='<dl class=\"charge1224-bridge\"><dt>Recorded charges</dt><dd>'",
       "const bridge='<dl class=\"charge1224-bridge\"><dt>'+(m.customerReview12451?'Known charge subtotal':'Recorded charges')+'</dt><dd>'",
       'assurance bridge labels subtotal'),
      ('<div class="charge1224-figures"><div><span>Recorded charges</span><strong>',
       "<div class=\"charge1224-figures\"><div><span>'+(m.customerReview12451?'Known charge subtotal':'Recorded charges')+'</span><strong>",
       'assurance summary labels subtotal'),
    ]
    for before,after,label in changes:
        text=rep(text,before,after,label,path)
    return text
